// 高校受験 社会（formulas-koko-shakai.ts）の 1番目〜12番目の項目の、動く図解スライド。
// キーは項目の label（買い切りの識別キーと同じ）。「なぜ？」の連鎖で、根っこまでたどる。
import type { DiagramElement, DiagramFigure } from './figures';
import { C, FILL, bx, lb, ar, ln, ci, sc, show, band, fresh, flow, type Slide } from './diagram-kit';

const BY = 152; // 下の帯の開始位置
const cap = (t: string, color: string = C.main, fill: string = FILL.warm, size = 13): DiagramElement[] =>
  band(BY, bx(14, 168, 292, 40, t, color, fill, size));
/** 画面を描きなおして、下の帯に1行の結論を出す。 */
const S = (note: string, fig: DiagramElement[], c?: [string, string?, string?, number?]): Slide => ({
  note,
  add: [...fresh(...fig), ...(c ? cap(c[0], c[1] ?? C.main, c[2] ?? FILL.warm, c[3] ?? 13) : [])],
});
const F = (labels: string[], y: number, o?: { h?: number; color?: string; fill?: string; size?: number }): DiagramElement[] =>
  flow(labels, y, o).flat();

