// ══ 3. 世界の気候帯と雨温図 ══
const AX = 34;
const climate = (temps: number[], rains: number[], tc: string = C.red, rc: string = C.blue): DiagramElement[] => {
  const out: DiagramElement[] = [ln(AX - 2, 14, AX - 2, 132, C.gray), ln(AX - 2, 132, AX + 156, 132, C.gray)];
  rains.forEach((r, i) => {
    const h = Math.max(1, r * 0.25);
    out.push(bx(AX + i * 13, 132 - h, 10, h, undefined, rc, FILL.blue));
  });
  const y = (t: number) => 110 - t * 2.4;
  temps.slice(1).forEach((t, i) => out.push(ln(AX + 5 + i * 13, y(temps[i]), AX + 5 + (i + 1) * 13, y(t), tc, false, 2.5)));
  return out;
};
